import (
	"strings"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"github.com/docker/docker-agent/pkg/agent"
	"github.com/docker/docker-agent/pkg/chat"
	"github.com/docker/docker-agent/pkg/session"
	"github.com/docker/docker-agent/pkg/team"
	"github.com/docker/docker-agent/pkg/tools"
)

// TestCompactIfNeeded_IgnoresSubSessionTokens is a regression test for
// issue #2871: in a multi-agent run, the tokens accumulated inside a
// transfer_task sub-session were counted by the proactive compaction
// trigger (GetAllMessages recurses into sub-sessions) even though they
// never enter the parent's prompt (GetMessages skips sub-session items).
// The phantom tokens made the parent compact its own tiny conversation;
// with everything fitting the keep budget that meant "compact
// everything, keep nothing" — the agent's next prompt was just the
// summary and it halted with a confused "no conversation history" reply.
func TestCompactIfNeeded_IgnoresSubSessionTokens(t *testing.T) {
	prov := &mockProvider{id: "test/model", stream: &mockStream{}}
	root := agent.New("root", "agent", agent.WithModel(prov))
	tm := team.New(team.WithAgents(root))

	rt, err := NewLocalRuntime(tm,
		WithSessionCompaction(true),
		WithModelStore(mockModelStoreWithLimit{limit: 100_000}))
	require.NoError(t, err)

	sess := session.New(session.WithUserMessage("build the app"))
	messageCountBefore := len(sess.OwnMessages())

	// Simulate a completed transfer_task tool call: a sub-session holding
	// far more content than the parent's context limit, plus a small
	// tool-result message on the parent itself.
	sub := session.New(session.WithUserMessage("subtask"))
	sub.AddMessage(session.NewAgentMessage("worker", &chat.Message{
		Role:    chat.MessageRoleAssistant,
		Content: strings.Repeat("z", 600_000), // ~150k estimated tokens
	}))
	sess.AddMessage(session.NewAgentMessage("root", &chat.Message{
		Role:      chat.MessageRoleAssistant,
		ToolCalls: []tools.ToolCall{{ID: "t1", Function: tools.FunctionCall{Name: "transfer_task"}}},
	}))
	sess.AddSubSession(sub)
	sess.AddMessage(session.NewAgentMessage("root", &chat.Message{
		Role:       chat.MessageRoleTool,
		ToolCallID: "t1",
		Content:    "subtask done",
	}))

	events := make(chan Event, 16)
	rt.compactIfNeeded(t.Context(), sess, root, 100_000, messageCountBefore, NewChannelSink(events))
	close(events)

	for ev := range events {
		_, isCompaction := ev.(*SessionCompactionEvent)
		assert.False(t, isCompaction,
			"sub-session tokens must not trigger compaction of the parent session")
	}
}

// TestCompactIfNeeded_TriggersOnOwnMessages pins the complementary case:
// large tool results recorded directly on the session still trigger the
// proactive compaction.
func TestCompactIfNeeded_TriggersOnOwnMessages(t *testing.T) {
	prov := &mockProvider{id: "test/model", stream: &mockStream{}}
	root := agent.New("root", "agent", agent.WithModel(prov))
	tm := team.New(team.WithAgents(root))

	rt, err := NewLocalRuntime(tm,
		WithSessionCompaction(true),
		WithModelStore(mockModelStoreWithLimit{limit: 100_000}))
	require.NoError(t, err)

	sess := session.New(session.WithUserMessage("build the app"))
	messageCountBefore := len(sess.OwnMessages())

	sess.AddMessage(session.NewAgentMessage("root", &chat.Message{
		Role:      chat.MessageRoleAssistant,
		ToolCalls: []tools.ToolCall{{ID: "t1", Function: tools.FunctionCall{Name: "shell"}}},
	}))
	sess.AddMessage(session.NewAgentMessage("root", &chat.Message{
		Role:       chat.MessageRoleTool,
		ToolCallID: "t1",
		Content:    strings.Repeat("z", 600_000), // ~150k estimated tokens
	}))

	events := make(chan Event, 16)
	rt.compactIfNeeded(t.Context(), sess, root, 100_000, messageCountBefore, NewChannelSink(events))
	close(events)

	sawCompaction := false
	for ev := range events {
		if _, ok := ev.(*SessionCompactionEvent); ok {
			sawCompaction = true
		}
	}
	assert.True(t, sawCompaction, "large own tool results must still trigger compaction")
}

package toolinstall

import (
	"testing"

	"github.com/stretchr/testify/assert"
)

func TestPackageInstallHosts_GoPackage(t *testing.T) {
	t.Parallel()

	// Go packages go through `go install`, which pulls from the Go
	// module proxy + checksum DB and may bootstrap a newer toolchain
	// from go.dev / dl.google.com / storage.googleapis.com. The
	// registry lookup itself still hits raw.githubusercontent.com
	// and api.github.com, so those must be present too.
	pkg := &Package{Type: "go_install", RepoOwner: "golang", RepoName: "tools"}

	got := pkg.InstallHosts()

	assert.ElementsMatch(t, []string{
		"raw.githubusercontent.com",
		"api.github.com",
		"proxy.golang.org",
		"sum.golang.org",
		"go.dev",
		"dl.google.com",
		"storage.googleapis.com",
	}, got, "go_install package must allow Go module proxy + toolchain bootstrap, not GitHub releases")

	// Crucially, GitHub release hosts must not be opened for a Go
	// package — `go install` never reaches them.
	assert.NotContains(t, got, "github.com")
	assert.NotContains(t, got, "objects.githubusercontent.com")
	assert.NotContains(t, got, "codeload.github.com")
}

func TestPackageInstallHosts_GitHubRelease(t *testing.T) {
	t.Parallel()

	pkg := &Package{Type: "github_release", RepoOwner: "junegunn", RepoName: "fzf"}

	got := pkg.InstallHosts()

	assert.ElementsMatch(t, []string{
		"raw.githubusercontent.com",
		"api.github.com",
		"github.com",
		"objects.githubusercontent.com",
		"codeload.github.com",
	}, got, "github_release package must allow GitHub release hosts, not the Go module proxy")

	// And a github_release tool must NOT punch holes for the Go
	// toolchain bootstrap — those hosts have nothing to do with it.
	assert.NotContains(t, got, "proxy.golang.org")
	assert.NotContains(t, got, "go.dev")
	assert.NotContains(t, got, "dl.google.com")
}

func TestPackageInstallHosts_SortedAndDeduped(t *testing.T) {
	t.Parallel()

	pkg := &Package{Type: "go_install"}
	got := pkg.InstallHosts()

	for i := 1; i < len(got); i++ {
		assert.Less(t, got[i-1], got[i],
			"InstallHosts must return sorted, dedup'd entries; got %v", got)
	}
}

func TestFallbackHosts_CoversBothPaths(t *testing.T) {
	t.Parallel()

	// FallbackHosts is what we open when we *cannot* narrow per
	// package (registry unreachable, no cache). It must therefore
	// cover every host any install path might reach — both Go
	// module proxy + toolchain AND GitHub releases — otherwise the
	// fallback is silently incomplete.
	got := FallbackHosts()

	for _, want := range []string{
		"raw.githubusercontent.com", "api.github.com",
		"proxy.golang.org", "sum.golang.org",
		"go.dev", "dl.google.com", "storage.googleapis.com",
		"github.com", "objects.githubusercontent.com", "codeload.github.com",
	} {
		assert.Contains(t, got, want, "fallback must cover %q", want)
	}
}

func TestMergeHosts_DedupAndSort(t *testing.T) {
	t.Parallel()

	got := mergeHosts(
		[]string{"b", "a"},
		[]string{"a", "c"},
	)
	assert.Equal(t, []string{"a", "b", "c"}, got)
}

